if(section==='language'){
card.append(node('p','Cada pessoa pode escolher seu próprio idioma pelo /idioma ou pelo botão Idioma em /ajuda e /help. A escolha pessoal vem primeiro; no modo automático, a Suzuki usa o idioma identificado na última interação com o Discord. O padrão do servidor vale quando esse idioma ainda não foi identificado.'));
const choices={'pt-BR':'Português (Brasil)',en:'English',es:'Español',ja:'日本語',de:'Deutsch',fr:'Français',ko:'한국어',tr:'Türkçe',id:'Bahasa Indonesia',hi:'हिन्दी'};
const l=node('label',undefined,'field'),s=node('select');s.name='language';for(const [code,label] of Object.entries(choices))s.add(new Option(label,code));s.value=data.settings.language||'pt-BR';l.append(node('span','Idioma padrão deste servidor'),s);card.append(l,node('small','Use Salvar alterações para mudar o padrão do servidor.','help'));
const mine=node('section',undefined,'card'),ml=node('label',undefined,'field'),ms=node('select');ms.add(new Option('Automático (idioma do Discord)','default'));for(const [code,label] of Object.entries(choices))ms.add(new Option(label,code));ms.value=data.personal_language||'default';ms.oninput=e=>e.stopPropagation();ml.append(node('span','Meu idioma pessoal'),ms);const b=node('button','Salvar meu idioma','secondary');b.type='button';b.onclick=()=>{if(dirty){status.textContent='Salve ou descarte as alterações do servidor antes de mudar seu idioma pessoal.';return}operation('guild_action',{guild:data.guild.id,action:'language_personal',target:ms.value,reason:'Idioma pessoal escolhido no site'})};mine.append(node('h3','Só para você'),ml,b,node('p','Esta escolha acompanha sua conta e não altera os outros membros. Textos escritos nas imagens e gravações prontas mantêm o idioma original.','help'));card.append(mine);
}
