if(section==='events'){card.append(node('p','Escolha quais acontecimentos a Suzuki deve registrar no seu servidor.'),channelSelect('logs_channel','Canal dos registros'));for(const [key,label]of Object.entries(fields))if(!['log_messages','log_voice'].includes(key))card.append(toggle(key,label));card.append(node('p','Mensagens editadas, apagadas e movimentos em call são configurados em Mensagens e calls.','help'))}
if(section==='invites')card.append(node('p','Apaga convites não permitidos e registra um aviso. Administradores e moderadores não são bloqueados.'),toggle('invite_enabled','Ativar bloqueador de convites'),channels('invite_ignore_channels','Canais liberados'),textField('invite_allowed_codes','Códigos permitidos','Um código por linha, como abc123.'));
