if(section==='warnings'){card.append(node('p','Use /avisar no Discord para registrar avisos. O limite abaixo aplica timeout aos múltiplos desse total.'));for(const [key,label,min,max]of [['warn_threshold','A cada quantos avisos? (0 desativa)',0,100],['warn_minutes','Duração do timeout em minutos',1,1440]]){const l=node('label',undefined,'field'),i=node('input');i.name=key;i.type='number';i.min=min;i.max=max;i.step=1;i.value=data.settings[key];l.append(node('span',label),i);card.append(l)}}
